const data = $memory.getJson("busquedaTermino", {});

const nombre = data[0].Nombre;
const identificacion = data[0].Identificación;

$memory.set("nombreGEA", nombre, 86400)
$memory.set("identificacion", identificacion, 86400)

const aceptar = $memory.get('response', '');

if (["si", "sí"].includes(aceptar.toLowerCase())) {
   $memory.set('acepta', true, 86400)
} else {
    $memory.set('acepta', false, 86400)
}
